// ============================================================================
// YOUTUBE ORIGINALS STYLE CINEMATIC INTRO SCREEN
// Golden Yellow Slogan ("Understanding Microbes, Strengthening Health")
// emerges from between the Top & Bottom splitting golden bars
// ============================================================================
class YouTubeOriginalStyleIntroScreen extends StatefulWidget {
  const YouTubeOriginalStyleIntroScreen({super.key});

  @override
  State<YouTubeOriginalStyleIntroScreen> createState() =>
      _YouTubeOriginalStyleIntroScreenState();
}

class _YouTubeOriginalStyleIntroScreenState
    extends State<YouTubeOriginalStyleIntroScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;
  bool _navigated = false;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 3800),
    )..forward();

    _ctrl.addStatusListener((AnimationStatus status) {
      if (status == AnimationStatus.completed) {
        _goNext();
      }
    });
  }

  void _goNext() {
    if (_navigated || !mounted) return;
    _navigated = true;
    Navigator.of(context).pushReplacement(
      PageRouteBuilder<void>(
        transitionDuration: const Duration(milliseconds: 480),
        pageBuilder: (BuildContext context, Animation<double> a1,
                Animation<double> a2) =>
            const MainDepartmentShell(),
        transitionsBuilder: (BuildContext context, Animation<double> anim,
            Animation<double> sec, Widget child) {
          return FadeTransition(opacity: anim, child: child);
        },
      ),
    );
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  double _interval(double begin, double end, Curve curve) {
    final double t = _ctrl.value;
    if (t <= begin) return 0.0;
    if (t >= end) return 1.0;
    return curve.transform((t - begin) / (end - begin));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF07111E),
      body: Stack(
        children: <Widget>[
          Positioned.fill(
            child: Container(
              decoration: const BoxDecoration(
                gradient: RadialGradient(
                  center: Alignment(0.0, -0.18),
                  radius: 1.05,
                  colors: <Color>[
                    Color(0xFF102A3F),
                    Color(0xFF091626),
                    Color(0xFF050B14),
                  ],
                ),
              ),
            ),
          ),
          SafeArea(
            child: AnimatedBuilder(
              animation: _ctrl,
              builder: (BuildContext context, Widget? _) {
                final double badgePop =
                    _interval(0.0, 0.30, Curves.easeOutBack);
                final double badgeSheen =
                    _interval(0.18, 0.55, Curves.easeInOut);
                final double lineDraw =
                    _interval(0.24, 0.46, const Cubic(0.22, 1.0, 0.36, 1.0));
                final double barSplit =
                    _interval(0.44, 0.72, const Cubic(0.16, 1.0, 0.3, 1.0));
                final double deptReveal =
                    _interval(0.60, 0.88, Curves.easeOutCubic);

                final double maxLineWidth =
                    math.min(MediaQuery.of(context).size.width - 40, 340.0);
                final double currentLineWidth = maxLineWidth * lineDraw;
                final double splitGap = 52.0 * barSplit;

                return Center(
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 20),
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: <Widget>[
                        Opacity(
                          opacity: badgePop.clamp(0.0, 1.0),
                          child: Transform.scale(
                            scale: 0.76 + (0.24 * badgePop),
                            child: Stack(
                              alignment: Alignment.center,
                              children: <Widget>[
                                const OriginalBadgeLogo(
                                  size: 168,
                                  borderRadius: 34,
                                  showGlow: true,
                                ),
                                ClipRRect(
                                  borderRadius: BorderRadius.circular(34),
                                  child: SizedBox(
                                    width: 168,
                                    height: 168,
                                    child: FractionalTranslation(
                                      translation: Offset(
                                          -1.3 + (badgeSheen * 2.6), 0.0),
                                      child: Transform.rotate(
                                        angle: -0.45,
                                        child: Container(
                                          width: 56,
                                          height: 240,
                                          decoration: BoxDecoration(
                                            gradient: LinearGradient(
                                              colors: <Color>[
                                                Colors.white.withOpacity(0.0),
                                                Colors.white.withOpacity(0.24),
                                                Colors.white.withOpacity(0.0),
                                              ],
                                            ),
                                          ),
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                        const SizedBox(height: 30),

                        if (lineDraw > 0.01)
                          SizedBox(
                            width: maxLineWidth,
                            height: splitGap + 14,
                            child: Stack(
                              alignment: Alignment.center,
                              children: <Widget>[
                                ClipRect(
                                  child: Align(
                                    alignment: Alignment.center,
                                    heightFactor: barSplit.clamp(0.0, 1.0),
                                    child: Opacity(
                                      opacity: barSplit.clamp(0.0, 1.0),
                                      child: Transform.scale(
                                        scale: 0.90 + (0.10 * barSplit),
                                        child: const Padding(
                                          padding: EdgeInsets.symmetric(
                                              horizontal: 6),
                                          child: Text(
                                            'Understanding Microbes, Strengthening Health',
                                            textAlign: TextAlign.center,
                                            style: TextStyle(
                                              fontSize: 13.0,
                                              fontWeight: FontWeight.w800,
                                              color: AppColors.gold,
                                              letterSpacing: 0.45,
                                              shadows: <Shadow>[
                                                Shadow(
                                                  color: Color(0x80F5B82E),
                                                  blurRadius: 10,
                                                ),
                                              ],
                                            ),
                                          ),
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                                Positioned(
                                  top: 0,
                                  child: Container(
                                    width: currentLineWidth,
                                    height: 2.5,
                                    decoration: BoxDecoration(
                                      borderRadius: BorderRadius.circular(3),
                                      gradient: const LinearGradient(
                                        colors: <Color>[
                                          Color(0x00F5B82E),
                                          AppColors.gold,
                                          AppColors.goldBright,
                                          AppColors.gold,
                                          Color(0x00F5B82E),
                                        ],
                                      ),
                                      boxShadow: <BoxShadow>[
                                        BoxShadow(
                                          color:
                                              AppColors.gold.withOpacity(0.55),
                                          blurRadius: 8,
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                                Positioned(
                                  bottom: 0,
                                  child: Container(
                                    width: currentLineWidth,
                                    height: 2.5,
                                    decoration: BoxDecoration(
                                      borderRadius: BorderRadius.circular(3),
                                      gradient: const LinearGradient(
                                        colors: <Color>[
                                          Color(0x00F5B82E),
                                          AppColors.gold,
                                          AppColors.goldBright,
                                          AppColors.gold,
                                          Color(0x00F5B82E),
                                        ],
                                      ),
                                      boxShadow: <BoxShadow>[
                                        BoxShadow(
                                          color:
                                              AppColors.gold.withOpacity(0.55),
                                          blurRadius: 8,
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          )
                        else
                          const SizedBox(height: 66),

                        const SizedBox(height: 16),

                        Opacity(
                          opacity: deptReveal.clamp(0.0, 1.0),
                          child: Transform.translate(
                            offset: Offset(0, (1.0 - deptReveal) * 10),
                            child: Column(
                              children: <Widget>[
                                const Text(
                                  'Microbiology Department',
                                  textAlign: TextAlign.center,
                                  style: TextStyle(
                                    fontSize: 16.5,
                                    fontWeight: FontWeight.w900,
                                    color: Colors.white,
                                    letterSpacing: 0.4,
                                  ),
                                ),
                                const SizedBox(height: 5),
                                Text(
                                  'Faculty of Pharmacy, Beni-Suef University',
                                  textAlign: TextAlign.center,
                                  style: TextStyle(
                                    fontSize: 11.8,
                                    fontWeight: FontWeight.w600,
                                    color: Colors.white.withOpacity(0.76),
                                    letterSpacing: 0.25,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
          Positioned(
            bottom: 24,
            right: 20,
            child: TextButton.icon(
              onPressed: _goNext,
              style: TextButton.styleFrom(
                foregroundColor: Colors.white70,
                backgroundColor: Colors.white.withOpacity(0.08),
                padding:
                    const EdgeInsets.symmetric(horizontal: 14, vertical: 7),
