                  side: BorderSide(color: Colors.white.withOpacity(0.14)),
                ),
              ),
              icon: const Icon(Icons.skip_next_rounded,
                  size: 16, color: AppColors.gold),
              label: const Text(
                'Skip',
                style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700),
              ),
