// FACEBOOK-STYLE TOP FLOATING CIRCULAR REFRESH INDICATOR
// ============================================================================
class TopFloatingCircularLoader extends StatelessWidget {
  final bool visible;
  const TopFloatingCircularLoader({super.key, required this.visible});

  @override
  Widget build(BuildContext context) {
    return IgnorePointer(
      ignoring: true,
      child: AnimatedSlide(
        duration: const Duration(milliseconds: 250),
        curve: Curves.easeOutBack,
        offset: visible ? const Offset(0, 0.0) : const Offset(0, -2.2),
        child: AnimatedOpacity(
          duration: const Duration(milliseconds: 190),
          opacity: visible ? 1.0 : 0.0,
          child: Padding(
            padding: const EdgeInsets.only(top: 10),
            child: Align(
              alignment: Alignment.topCenter,
              child: Container(
                width: 38,
                height: 38,
                padding: const EdgeInsets.all(8.5),
                decoration: BoxDecoration(
                  color: Colors.white,
                  shape: BoxShape.circle,
                  boxShadow: <BoxShadow>[
                    BoxShadow(
                      color: Colors.black.withOpacity(0.22),
                      blurRadius: 12,
                      offset: const Offset(0, 4),
                    ),
                  ],
                ),
                child: const CircularProgressIndicator(
                  strokeWidth: 2.8,
                  valueColor:
                      AlwaysStoppedAnimation<Color>(AppColors.emeraldDark),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

// ============================================================================
// MAIN DEPARTMENT SHELL
// Renders clean embedded HTML directly (bypassing doGet Malformed HTML errors)
// while syncing all data in real-time via POST to GAS_WEB_APP_URL
// ============================================================================
class MainDepartmentShell extends StatefulWidget {
  const MainDepartmentShell({super.key});

  @override
  State<MainDepartmentShell> createState() => _MainDepartmentShellState();
}

class _MainDepartmentShellState extends State<MainDepartmentShell> {
  final PageController _pageController = PageController(initialPage: 0);
  int _activeIndex = 0; // 0 = Doctor View, 1 = Super Admin View
  bool _doctorLoggedIn = false;
  bool _superLoggedIn = false;
  bool _isLoadingDoctor = true;
  bool _isLoadingSuper = true;

  InAppWebViewController? _doctorWebCtrl;
  InAppWebViewController? _superWebCtrl;

  bool get _isCurrentLoading =>
      _activeIndex == 0 ? _isLoadingDoctor : _isLoadingSuper;

  bool get _isAnyLoggedIn => _doctorLoggedIn || _superLoggedIn;

  void _switchToRole(int targetIndex) {
    if (_activeIndex != targetIndex) {
      setState(() => _activeIndex = targetIndex);
      _pageController.animateToPage(
        targetIndex,
        duration: const Duration(milliseconds: 340),
        curve: Curves.easeOutCubic,
      );
    }
    final InAppWebViewController? ctrl =
        targetIndex == 0 ? _doctorWebCtrl : _superWebCtrl;
    final String sub = targetIndex == 0 ? 'home' : 'superadmin';
    ctrl?.evaluateJavascript(
      source:
          "if(typeof navigateStaffSubpage==='function'){navigateStaffSubpage('$sub');}",
    );
  }

  Future<void> _refreshActiveView() async {
    if (_activeIndex == 0) {
      setState(() => _isLoadingDoctor = true);
      await _doctorWebCtrl?.evaluateJavascript(
        source: "if(typeof initStaffApp==='function'){initStaffApp();}",
      );
      await Future<void>.delayed(const Duration(milliseconds: 420));
      if (mounted) setState(() => _isLoadingDoctor = false);
    } else {
      setState(() => _isLoadingSuper = true);
      await _superWebCtrl?.evaluateJavascript(
        source:
            "if(typeof refreshMasterAllData==='function' && masterSession && masterSession.loggedIn){refreshMasterAllData();}else if(typeof initStaffApp==='function'){initStaffApp();}",
      );
      await Future<void>.delayed(const Duration(milliseconds: 420));
      if (mounted) setState(() => _isLoadingSuper = false);
    }
  }

  void _openStudentServices() {
    Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (BuildContext context) => const StudentServicesScreen(),
      ),
    );
  }

  @override
  void dispose() {
    _pageController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (bool didPop, Object? _) async {
        if (didPop) return;
        if (_activeIndex == 1 && !_superLoggedIn) {
          _switchToRole(0);
          return;
        }
        final InAppWebViewController? ctrl =
            _activeIndex == 0 ? _doctorWebCtrl : _superWebCtrl;
        if (ctrl != null) {
          await ctrl.evaluateJavascript(
            source:
                "if(typeof navigateStaffSubpage==='function' && currentStaffSubpage!=='home'){navigateStaffSubpage('home');}",
          );
        }
      },
      child: Scaffold(
        backgroundColor: AppColors.slateBg,
        appBar: PreferredSize(
          preferredSize: const Size.fromHeight(54),
          child: Container(
            decoration: const BoxDecoration(
              color: AppColors.navyHeader,
              border: Border(
                bottom: BorderSide(color: Color(0xFF1E293B), width: 1),
              ),
            ),
            child: SafeArea(
              bottom: false,
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 10),
                child: Row(
                  children: <Widget>[
                    const OriginalBadgeLogo(size: 34, borderRadius: 8),
                    const SizedBox(width: 8),
                    const Expanded(
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: <Widget>[
                          Text(
                            'Microbiology Department',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              fontSize: 12.2,
                              fontWeight: FontWeight.w900,
                              color: Colors.white,
                              letterSpacing: 0.2,
                            ),
                          ),
                          Text(
                            'Faculty of Pharmacy • BSU',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              fontSize: 10.0,
                              fontWeight: FontWeight.w700,
                              color: AppColors.gold,
                            ),
                          ),
                        ],
                      ),
                    ),
                    // Role Switch Button (Super Admin <-> Doctor)
                    InkWell(
                      onTap: () => _switchToRole(_activeIndex == 0 ? 1 : 0),
                      borderRadius: BorderRadius.circular(9),
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8.5, vertical: 5.5),
                        decoration: BoxDecoration(
                          color: _activeIndex == 1
                              ? AppColors.gold
                              : const Color(0xFF1E293B),
                          borderRadius: BorderRadius.circular(9),
                          border: Border.all(
                            color: _activeIndex == 1
                                ? AppColors.gold
                                : AppColors.gold.withOpacity(0.45),
                          ),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: <Widget>[
                            Icon(
                              _activeIndex == 1
                                  ? Icons.medical_services_rounded
                                  : Icons.shield_rounded,
                              size: 13,
                              color: _activeIndex == 1
                                  ? AppColors.navyHeader
                                  : AppColors.gold,
                            ),
                            const SizedBox(width: 4),
                            Text(
                              _activeIndex == 1 ? 'Doctor' : 'Super Admin',
                              style: TextStyle(
                                fontSize: 10.2,
                                fontWeight: FontWeight.w800,
                                color: _activeIndex == 1
                                    ? AppColors.navyHeader
                                    : AppColors.gold,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                    const SizedBox(width: 4),
                    SizedBox(
                      width: 30,
                      height: 30,
                      child: IconButton(
                        padding: EdgeInsets.zero,
                        onPressed: _refreshActiveView,
                        icon: const Icon(
                          Icons.refresh_rounded,
                          size: 17,
                          color: Colors.white70,
                        ),
                      ),
                    ),
                    const SizedBox(width: 4),
                    // Compact Top-Right Students Button
                    InkWell(
                      onTap: _openStudentServices,
                      borderRadius: BorderRadius.circular(8),
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8.5, vertical: 5.5),
                        decoration: BoxDecoration(
                          color: AppColors.emeraldDark,
                          borderRadius: BorderRadius.circular(8),
                          border: Border.all(
                              color: AppColors.emerald.withOpacity(0.55)),
                        ),
                        child: const Row(
                          mainAxisSize: MainAxisSize.min,
                          children: <Widget>[
                            Icon(Icons.school_rounded,
                                size: 12.5, color: Colors.white),
                            SizedBox(width: 4),
                            Text(
                              'Students',
                              style: TextStyle(
                                fontSize: 10.2,
                                fontWeight: FontWeight.w800,
                                color: Colors.white,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
        body: Stack(
          children: <Widget>[
            PageView(
              controller: _pageController,
              physics: _isAnyLoggedIn
                  ? const NeverScrollableScrollPhysics()
                  : const BouncingScrollPhysics(),
              onPageChanged: (int idx) {
                setState(() => _activeIndex = idx);
              },
              children: <Widget>[
                // Page 0: Doctor & Staff Interface
                _EmbeddedPortalPane(
                  htmlContent: kEmbeddedAdminHtml,
                  initialSubpage: 'home',
                  onControllerCreated: (InAppWebViewController c) =>
                      _doctorWebCtrl = c,
                  onLoadingChanged: (bool loading) {
                    if (mounted) setState(() => _isLoadingDoctor = loading);
                  },
                  onLoginStateChanged: (bool loggedIn) {
                    if (mounted && _doctorLoggedIn != loggedIn) {
                      setState(() => _doctorLoggedIn = loggedIn);
                    }
                  },
                ),
                // Page 1: Super Admin Interface
                _EmbeddedPortalPane(
                  htmlContent: kEmbeddedAdminHtml,
                  initialSubpage: 'superadmin',
                  onControllerCreated: (InAppWebViewController c) =>
                      _superWebCtrl = c,
                  onLoadingChanged: (bool loading) {
                    if (mounted) setState(() => _isLoadingSuper = loading);
                  },
                  onLoginStateChanged: (bool loggedIn) {
                    if (mounted && _superLoggedIn != loggedIn) {
                      setState(() => _superLoggedIn = loggedIn);
                    }
                  },
                ),
              ],
            ),

            // Pre-Login Floating Edge Swipe Handle
            if (!_isAnyLoggedIn)
              Positioned(
                right: _activeIndex == 0 ? 0 : null,
                left: _activeIndex == 1 ? 0 : null,
                top: MediaQuery.of(context).size.height * 0.36,
                child: GestureDetector(
                  onTap: () => _switchToRole(_activeIndex == 0 ? 1 : 0),
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 6, vertical: 12),
                    decoration: BoxDecoration(
                      color: AppColors.navyHeader.withOpacity(0.88),
                      borderRadius: _activeIndex == 0
                          ? const BorderRadius.only(
                              topLeft: Radius.circular(12),
                              bottomLeft: Radius.circular(12),
                            )
                          : const BorderRadius.only(
                              topRight: Radius.circular(12),
                              bottomRight: Radius.circular(12),
                            ),
                      border: Border.all(
                        color: AppColors.gold.withOpacity(0.55),
                        width: 1,
                      ),
                      boxShadow: <BoxShadow>[
                        BoxShadow(
                          color: Colors.black.withOpacity(0.25),
                          blurRadius: 8,
                        ),
                      ],
                    ),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: <Widget>[
                        Icon(
                          _activeIndex == 0
                              ? Icons.chevron_left_rounded
                              : Icons.chevron_right_rounded,
                          color: AppColors.gold,
                          size: 18,
                        ),
                        const SizedBox(height: 2),
                        RotatedBox(
                          quarterTurns: 3,
                          child: Text(
                            _activeIndex == 0 ? 'SUPER ADMIN' : 'DOCTOR',
                            style: const TextStyle(
                              fontSize: 8.5,
                              fontWeight: FontWeight.w900,
                              color: Colors.white,
                              letterSpacing: 0.8,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),

            TopFloatingCircularLoader(visible: _isCurrentLoading),
          ],
        ),
      ),
    );
  }
}

// ============================================================================
// EMBEDDED PORTAL WEBVIEW PANE (Direct Render + Real-Time Sync)
// ============================================================================
class _EmbeddedPortalPane extends StatefulWidget {
  final String htmlContent;
  final String initialSubpage;
  final ValueChanged<InAppWebViewController> onControllerCreated;
  final ValueChanged<bool> onLoadingChanged;
  final ValueChanged<bool> onLoginStateChanged;

  const _EmbeddedPortalPane({
    required this.htmlContent,
    required this.initialSubpage,
    required this.onControllerCreated,
    required this.onLoadingChanged,
    required this.onLoginStateChanged,
  });

  @override
  State<_EmbeddedPortalPane> createState() => _EmbeddedPortalPaneState();
}

class _EmbeddedPortalPaneState extends State<_EmbeddedPortalPane>
    with AutomaticKeepAliveClientMixin {
  InAppWebViewController? _ctrl;
  Timer? _pollTimer;

  @override
  bool get wantKeepAlive => true;

  void _startLoginStateMonitor() {
    _pollTimer?.cancel();
    _pollTimer = Timer.periodic(const Duration(milliseconds: 1000), (_) async {
      final InAppWebViewController? c = _ctrl;
      if (c == null || !mounted) return;
      try {
        final Object? res = await c.evaluateJavascript(
          source: """
          (function() {
            var dLogged = (typeof docSession !== 'undefined' && docSession && docSession.loggedIn);
            var mLogged = (typeof masterSession !== 'undefined' && masterSession && masterSession.loggedIn);
            return (dLogged || mLogged) ? '1' : '0';
          })();
          """,
        );
        final bool loggedIn = res?.toString().contains('1') ?? false;
        widget.onLoginStateChanged(loggedIn);
      } catch (_) {}
    });
  }

  @override
  void dispose() {
    _pollTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    super.build(context);
    return InAppWebView(
      initialData: InAppWebViewInitialData(
        data: widget.htmlContent,
        mimeType: 'text/html',
        encoding: 'utf-8',
        baseUrl: WebUri('https://script.google.com/'),
      ),
      initialSettings: InAppWebViewSettings(
        javaScriptEnabled: true,
        domStorageEnabled: true,
        databaseEnabled: true,
        supportZoom: false,
        builtInZoomControls: false,
        displayZoomControls: false,
        useWideViewPort: true,
        loadWithOverviewMode: true,
        mediaPlaybackRequiresUserGesture: false,
        allowsInlineMediaPlayback: true,
        mixedContentMode: MixedContentMode.MIXED_CONTENT_ALWAYS_ALLOW,
      ),
      gestureRecognizers: <WebGestureFactory>{
        WebGestureFactory(() => VerticalDragGestureRecognizer()),
      },
      onWebViewCreated: (InAppWebViewController controller) {
        _ctrl = controller;
        widget.onControllerCreated(controller);
        _startLoginStateMonitor();
      },
      onLoadStart: (InAppWebViewController controller, WebUri? url) {
        widget.onLoadingChanged(true);
      },
      onLoadStop: (InAppWebViewController controller, WebUri? url) async {
        if (widget.initialSubpage != 'home') {
          final String sub = widget.initialSubpage;
          await controller.evaluateJavascript(
            source:
                "if(typeof navigateStaffSubpage==='function'){navigateStaffSubpage('$sub');}",
          );
        }
        widget.onLoadingChanged(false);
      },
      onReceivedError: (InAppWebViewController controller,
          WebResourceRequest request, WebResourceError error) {
        if (request.isForMainFrame ?? false) {
          widget.onLoadingChanged(false);
        }
      },
      shouldOverrideUrlLoading: (InAppWebViewController controller,
          NavigationAction navigationAction) async {
        final WebUri? uri = navigationAction.request.url;
        if (uri == null) return NavigationActionPolicy.ALLOW;
        final String urlStr = uri.toString();
        if (urlStr.contains('drive.google.com') ||
            urlStr.contains('docs.google.com/spreadsheets') ||
            urlStr.startsWith('mailto:') ||
            urlStr.startsWith('tel:') ||
            urlStr.contains('wa.me')) {
          final Uri? parsed = Uri.tryParse(urlStr);
          if (parsed != null) {
            await launchUrl(parsed, mode: LaunchMode.externalApplication);
            return NavigationActionPolicy.CANCEL;
          }
        }
        return NavigationActionPolicy.ALLOW;
      },
    );
  }
}

